    std::vector<canonical_segment> segments;
    auto in_fun = [&](auto i) { return data[i]; };
    auto out_fun = [&](auto cs) { segments.emplace_back(cs); };
    pgm::internal::make_segmentation(data.size(), epsilon, in_fun, out_fun);
    auto it = segments.begin();
